UNITS = [
    {"id": "PEDS-U138", "ch": 17, "n": 1, "title": "Rickets — Etiology and Pathophysiology", "sec": "Rickets · p69", "qs": [], "guide": "Rickets Occurs due to Vitamin D deficiency (Sunshine vitamin). Etiology Dietary deficiency (Fish, fish liver oil, egg yolk) Drugs Anti-epileptics (Phenytoin, phenobarbitone, carbamazepine) + Antitubercular (Isoniazid + Rifampicin) ↓ sunlight exposure Malabsorption Chronic liver disease. Pathophysiology Vit D deficiency → ↓ absorption Ca²⁺ & PO₄³⁻ → ↓ mineralization of bone → Weak bones (Disproportionate short stature: Short limbs, Pathological fractures, Deformity) + Cartilage hypertrophy at growth plate → Osteoid expansion → Swelling."},
    {"id": "PEDS-U139", "ch": 17, "n": 2, "title": "Rickets — Deformity: Head and Chest", "sec": "Deformity · p69", "qs": [], "guide": "Head 1. Craniotabes Softening of skull bone, Sponge ball/ping pong ball like consistency. Note Craniotabes also seen in Congenital syphilis, Hydrocephalus, Osteogenesis imperfecta. 2. ↑ size of fontanelles (Wide open) 3. Frontal bone bossing. Chest 1. Costochondral junction widening Rachitic rosary (Painless & round) AKA string of beads appearance. 2. Harrison's sulcus groove d/t pull of diaphragm on weakened ribs."},
    {"id": "PEDS-U140", "ch": 17, "n": 3, "title": "Rickets — Limbs, Other Findings and Investigations", "sec": "Limbs · p70", "qs": [], "guide": "Limbs 1. Widening of wrist 2. Genu varum/bow leg 3. Genu valgum/knock knees 4. Double malleolus sign (Cartilage hypertrophy Swelling above lateral malleolus). Other findings Delayed dentition Seizures/tetany in infants d/t acute hypocalcemia. Blood ↓ Vit D (↓ as HCC) ↓S.Ca²⁺→↑PTH→Normal S.Ca²⁺ ↓S.PO₄³⁻ D/t ↑ bone resorption by PTH ↑ALP. Vit D table Sufficiency >20, Insufficiency 12-20, Deficiency <12 ng/ml. X-Ray primary tool Loss of zone of provisional calcification (ZPC) white line Fraying (First sign) Cupping."},
    {"id": "PEDS-U141", "ch": 17, "n": 4, "title": "Rickets — Treatment and Monitoring Response", "sec": "Treatment · p71", "qs": [], "guide": "1. Daily dose of Vitamin D → Recommended Duration 12 weeks. Dose <1 year 2000 IU/day; >1 year 3000 IU/day. 2. Ca²⁺ supplement 50-75 mg/kg/day. Monitoring 1. X-Ray Preferred method, shows changes by 4 weeks, Healing with line of rickets (1st visible sign) 2. Biochemical investigation shows changes in 12 weeks."},
    {"id": "PEDS-U142", "ch": 17, "n": 5, "title": "Refractory Rickets — Definition and Familial Hypophosphatemic Rickets", "sec": "Refractory Rickets · p71", "qs": [], "guide": "Refractory Rickets No response to Vitamin D supplementation. Disorders seen 1. Familial hypophosphatemic rickets 2. Vitamin D dependent rickets (VDDR) 3. RTA associated rickets 4. CKD associated rickets. Familial hypophosphatemic X-linked dominant, m/c inherited form, PHEX gene mutation (phosphate regulation endopeptidase). Normal PHEX → Endopeptidase → Inactivated phosphatonin (FGF-23); mutation → No endopeptidase → Phosphatonin always active → ↑ PO₄³⁻ excretion urine → Hypophosphatemia. Features Lower limb deformities, No features of hypocalcemia (e.g. Tetany), Dental abnormalities Pulp exposure ↑ risk dental abscess."},
    {"id": "PEDS-U143", "ch": 17, "n": 6, "title": "Refractory Rickets — Treatment, VDDR and Approach Algorithm", "sec": "VDDR · p72", "qs": [], "guide": "Familial hypophosphatemic Treatment 1. Phosphate supplementation Joule solution (elemental phosphates) 2. Burosumab newer drug monoclonal antibody against FGF-23. VDDR Autosomal recessive, Defects in Vit D metabolism → Hypocalcemia. Features Classic rickets + Type II additional Ectodermal defects (Milia, epidermal cysts), Oligodontia (↓ teeth), Alopecia. Treatment Type I α calcidiol (active form of Vit D) + Ca²⁺ supplements; Type II High doses Vit D → partially overcome resistance → improves symptoms. Approach (biochemical values) High PO₄³⁻ → CKD associated (↓ excretion PO₄³⁻); Low PO₄³⁻ → ABG Acidosis(+) → RTA; Acidosis(−) → PTH High (response to ↓Ca²⁺) → VDDR; Normal → Familial hypophosphatemic."},
    {"id": "PEDS-U144", "ch": 17, "n": 7, "title": "Scurvy — Role of Vitamin C, Etiology, Features, X-Ray, Treatment", "sec": "Scurvy · p73", "qs": [], "guide": "Scurvy D/t Vitamin C deficiency. Role of Vit C 1. Collagen formation (Proline + Lysine → Hydroxylation requires Vit C → mature collagen) 2. Wound healing 3. Osteoid/bony trabeculae formation. Etiology Vit C deficient diet (Citrus fruits Lemon orange, Green vegetables) Intake of boiled/evaporated cow milk without fruit/vegetables. Early features Abnormal irritability ↓ appetite Anemia (Vit C needed for iron absorption). Bleeding Characteristic Gum bleeds, Perifollicular bleeding + corkscrew hair, Bone subperiosteal bleeding → Pain(+) → Pseudo paralysis → frog leg posture. Rosary Painful, Sharp or angulated. Diagnosis Mainly clinical; X-Ray Subperiosteal hemorrhage, Area of rarefaction (Trümmerfeld's zone central), Ring epiphysis, White line of Frankel, Pelken's spur (lateral). Treatment Oral Vit C 100-200 mg/day until lesion subsides."},
]

def q(num, sec, page, qtext, opts, ans, exp):
    assert len(opts)==4 and 0 <= ans <4
    return {"id": f"PEDS-C17-{num:03d}", "sec": sec, "page": page, "q": qtext, "opts": opts, "ans": ans, "exp": exp}

